type Token = { kind: "text" | "tag"; value: string; line: number; column: number };
type Node =
  | { kind: "text"; value: string }
  | { kind: "interpolation"; path: string; escaped: boolean; line: number; column: number }
  | { kind: "comment" }
  | { kind: "block"; name: "if" | "each"; path: string; yes: Node[]; no: Node[]; line: number; column: number };

type Scope = { value: unknown; index?: number; parent?: Scope };

function location(line: number, column: number): string {
  return ` at line ${line}, column ${column}`;
}

function tokenize(template: string): Token[] {
  const tokens: Token[] = [];
  let offset = 0;
  let line = 1;
  let column = 1;
  const advance = (text: string) => {
    const parts = text.split("\n");
    if (parts.length > 1) { line += parts.length - 1; column = parts[parts.length - 1].length + 1; }
    else column += text.length;
  };
  while (offset < template.length) {
    const start = template.indexOf("{{", offset);
    if (start < 0) { tokens.push({ kind: "text", value: template.slice(offset), line, column }); break; }
    if (start > offset) { const text = template.slice(offset, start); tokens.push({ kind: "text", value: text, line, column }); advance(text); }
    const tagLine = line, tagColumn = column;
    const triple = template.startsWith("{{{", start);
    const endMarker = triple ? "}}}" : "}}";
    const end = template.indexOf(endMarker, start + (triple ? 3 : 2));
    if (end < 0) throw new Error(`Unclosed tag${location(tagLine, tagColumn)}`);
    const value = template.slice(start + (triple ? 3 : 2), end).trim();
    const full = template.slice(start, end + endMarker.length);
    tokens.push({ kind: "tag", value: triple ? `{${value}}` : value, line: tagLine, column: tagColumn });
    advance(full); offset = end + endMarker.length;
  }
  return tokens;
}

function parse(template: string): Node[] {
  const tokens = tokenize(template);
  let position = 0;
  const parseList = (closing?: string): { nodes: Node[]; close?: string } => {
    const nodes: Node[] = [];
    while (position < tokens.length) {
      const token = tokens[position++];
      if (token.kind === "text") { nodes.push({ kind: "text", value: token.value }); continue; }
      const tag = token.value;
      if (tag.startsWith("/")) return { nodes, close: tag.slice(1).trim() };
      if (tag === "else") return { nodes, close: "else" };
      if (tag.startsWith("!")) { nodes.push({ kind: "comment" }); continue; }
      if (tag.startsWith("#")) {
        const match = tag.match(/^#(if|each)(?:\s+(.+?))?$/);
        if (!match || !match[2]) throw new Error(`Invalid or unknown block${location(token.line, token.column)}`);
        const name = match[1] as "if" | "each";
        const body = parseList(name);
        if (!body.close) throw new Error(`Unclosed ${name} block${location(token.line, token.column)}`);
