test("if and nested each", () => expect(render("{{#if ok}}Y{{else}}N{{/if}} {{#each xs}}{{@index}}={{this}}/{{name}};{{/each}}", { ok: 1, xs: ["a", "b"], name: "root" })).toBe("Y 0=a/root;1=b/root;"));
