    else if (node.kind === "interpolation") { const value = scalar(lookup(node.path, scope, root), node); output += node.escaped ? escapeHtml(value) : value; }
    else if (node.kind === "block") {
      const value = lookup(node.path, scope, root);
      if (node.name === "if") output += renderNodes(truthy(value) ? node.yes : node.no, scope, root);
      else if (Array.isArray(value)) output += value.length ? value.map((item, index) => renderNodes(node.yes, { value: item, index, parent: scope }, root)).join("") : renderNodes(node.no, scope, root);
      else throw new Error(`each expects an array${location(node.line, node.column)}`);
    }
  }
  return output;
}

export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { value: data }, data);
}
